    [Fact]
    public void Etapa2_POCEpatProcess_Coverage_AllReferenceNodesVisitedAcrossScenarios()
    {
        var pocScenarios = Etapa2Scenarios
            .Where(s => s.Process == "POC_EpatProcess")
            .Select(s => ScenarioFixtureLoader.LoadScenario(s.Id))
            .ToList();

        var coveredNodeIds = pocScenarios
            .SelectMany(d => d.Path ?? [])
            .Select(n => n.Id)
            .ToHashSet();

        var refPath = ReferenceScenario.Path!;
        var missing = refPath.Where(n => !coveredNodeIds.Contains(n.Id)).ToList();

        if (missing.Count > 0)
        {
            var details = string.Join(", ", missing.Select(n => $"'{n.Nome}' ({n.Id})"));
            Assert.Fail(
                $"Os seguintes nós do percurso de referência não foram cobertos por " +
                $"nenhum cenário POC_EpatProcess de etapa 2: {details}");
        }

        _output.WriteLine(
            $"[ok] Todos os {refPath.Count} nós do percurso de referência cobertos " +
            $"pelos {pocScenarios.Count} cenários POC_EpatProcess de etapa 2.");
    }

