    [Fact]
    public void Etapa2_POCEpatProcess_NonFlowNodes_PresentInAtLeastOneScenarioPath()
    {
        var pocScenarios = Etapa2Scenarios
            .Where(s => s.Process == "POC_EpatProcess")
            .Select(s => ScenarioFixtureLoader.LoadScenario(s.Id))
            .ToList();

        foreach (var (nodeId, expectedMechanism) in NonFlowNodes)
        {
            var scenariosWithNode = pocScenarios
                .Where(d => (d.Path ?? []).Any(n => n.Id == nodeId))
                .ToList();

            Assert.True(scenariosWithNode.Count > 0,
                $"Nó '{nodeId}' (entrouPor={expectedMechanism}) não encontrado no path " +
                $"de nenhum cenário POC_EpatProcess de etapa 2. " +
                $"O rasto deve incluí-lo na posição correta.");

            // Confirmar que o mecanismo na fixture bate com o declarado no card
            foreach (var sc in scenariosWithNode)
            {
                var node = (sc.Path ?? []).FirstOrDefault(n => n.Id == nodeId);
                if (node is null) continue;

                if (expectedMechanism is "None")
                    Assert.Null(node.EntrouPor);
                else
                    Assert.Equal(expectedMechanism, node.EntrouPor,
                        StringComparer.OrdinalIgnoreCase);
            }

            _output.WriteLine(
                $"[ok] {nodeId} (entrouPor={expectedMechanism}) presente em " +
                $"{scenariosWithNode.Count} cenário(s).");
        }
    }

