        // Valores lidos do oráculo (index.json) — nunca escritos aqui.
        Assert.Equal(48, byProcess.GetValueOrDefault("POC_EpatProcess", 0));
        Assert.Equal(4,  byProcess.GetValueOrDefault("DEAT0050", 0));
        Assert.Equal(18, byProcess.GetValueOrDefault("CALCPRPC", 0));
        Assert.Equal(12, byProcess.GetValueOrDefault("BSCENVPC", 0));
        Assert.Equal(18, byProcess.GetValueOrDefault("CRNOTPC", 0));

        foreach (var (proc, count) in byProcess.OrderBy(kv => kv.Key))
            _output.WriteLine($"[ok] {proc}: {count} cenários");
    }

    // =========================================================================
    // AC-ORACULO — sub-processos da etapa 2 declarados em descidas
    // =========================================================================

    /// <summary>
    /// Os cenários de sub-processo (DEAT0050, CALCPRPC, BSCENVPC, CRNOTPC)
    /// que pertencem à etapa 2 devem estar listados nas descidas do percurso
    /// de referência, confirmando que as chamadas de sub-processo são explícitas.
    /// </summary>
    [Fact]
    public void Etapa2_SubProcessScenarios_DeclaredInReferenceDescidas()
    {
        var descidas = ReferenceScenario.Descidas ?? [];
        var allDescidaCenarios = descidas
            .SelectMany(d => d.Cenarios ?? [])
            .ToHashSet();

        // Derivar os processos cobertos pelas descidas a partir do oracle (imutável).
        // CALCPRPC e CRNOTPC pertencem à etapa 2 mas são invocados transitivamente
        // (via PRPINTPC/BSCENVPC/CONTROPC) e não aparecem directamente em descidas[].
        var processesInDescidas = allDescidaCenarios
            .Select(id =>
            {
                // SC-DEAT0050-001 → DEAT0050; SC-PRPINTPC-001 → PRPINTPC; etc.
                var parts = id.Split('-');
                return parts.Length >= 2 ? parts[1] : string.Empty;
            })
            .Where(p => !string.IsNullOrEmpty(p))
            .ToHashSet(StringComparer.Ordinal);

        var subProcessScenarios = Etapa2Scenarios
            .Where(s => processesInDescidas.Contains(s.Process))
            .ToList();

        Assert.True(subProcessScenarios.Count > 0,
            "Nenhum cenário de sub-processo encontrado nos 100 de etapa 2 " +
            "cujo processo conste nas descidas de " + ReferenceScenarioId + ".");

        foreach (var sub in subProcessScenarios)
        {
            Assert.True(allDescidaCenarios.Contains(sub.Id),
                $"Cenário '{sub.Id}' (processo={sub.Process}) está nos 100 de etapa 2 " +
                $"mas não está declarado em nenhuma descida de {ReferenceScenarioId}. " +
                $"Descidas registadas: [{string.Join(", ", allDescidaCenarios.Take(10))}...]");

            _output.WriteLine($"[ok] {sub.Id} ({sub.Process}) declarado em descidas.");
        }
    }
}
